const body = $input.first().json?.body ?? $input.first().json ?? {};
const post_id = body.post_id ?? null;
const slug = body.slug ?? '';
const title = String(body.title ?? '').trim().slice(0, 300);
const excerpt = String(body.excerpt ?? '').trim().slice(0, 500);
const media_url = typeof body.media_url === 'string' && body.media_url.trim() ? body.media_url.trim() : null;
const link = typeof body.link === 'string' && body.link.trim() ? body.link.trim() : null;

const pageId = String($env.FACEBOOK_CENTRO_PAGE_ID ?? $env.FACEBOOK_CENTRO_INFORMATIVO_PAGE_ID ?? '').trim();
const token = String($env.FACEBOOK_CENTRO_PAGE_TOKEN ?? $env.FACEBOOK_CENTRO_INFORMATIVO_PAGE_TOKEN ?? $env.FACEBOOK_CENTRO_PAGE_ACCESS_TOKEN ?? '').trim();

if (!pageId) {
  console.warn('[CI-Facebook] Missing Page ID: set FACEBOOK_CENTRO_PAGE_ID (or FACEBOOK_CENTRO_INFORMATIVO_PAGE_ID) in n8n');
  return [{ json: { ok: false, error: 'missing_page_id', post_id } }];
}
if (!token) {
  console.warn('[CI-Facebook] Missing Page Access Token: set FACEBOOK_CENTRO_PAGE_TOKEN (or FACEBOOK_CENTRO_INFORMATIVO_PAGE_TOKEN) in n8n');
  return [{ json: { ok: false, error: 'missing_page_token', post_id } }];
}
if (!link) {
  return [{ json: { ok: false, error: 'missing_link', post_id } }];
}

const message = [title, excerpt, link].filter(Boolean).join('\n\n');
const version = String($env.MP26_META_GRAPH_VERSION ?? 'v21.0').trim();

return [{ json: { post_id, slug, title, excerpt, media_url, link, message, pageId, token, version } }];

const item = $input.first().json;
const postId = $('Prepare (check Page ID + Token)').first().json?.post_id ?? null;

if (item && item.error) {
  const msg = item.error.message ?? item.error.message ?? JSON.stringify(item.error);
  console.warn('[CI-Facebook] Facebook rejected:', msg);
  return [{ json: { ok: false, error: 'facebook_rejected', meta_message: msg, post_id: postId } }];
}

const fbPostId = item && (item.id ?? item.post_id);
if (fbPostId) {
  return [{ json: { ok: true, facebook_post_id: String(fbPostId), post_id: postId } }];
}
return [{ json: { ok: false, error: 'no_post_id_in_response', post_id: postId } }];

const err = $input.first().json?.error ?? $input.first().json?.message ?? 'facebook_request_failed';
const postId = $('Prepare (check Page ID + Token)').first().json?.post_id ?? null;
console.warn('[CI-Facebook] Facebook API error:', err);
return [{ json: { ok: false, error: 'facebook_rejected', meta_message: String(err), post_id: postId } }];
